package com.bank.routing;

import java.util.logging.*;

public class FindDuplicateDemo {
    private static final Logger log = Logger.getLogger(FindDuplicateDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RoutingCodeValidator validator = new RoutingCodeValidator();

        // n=6 slots hold values 1..5; value 3 is duplicated
        int[] codes = {1, 3, 4, 2, 3, 5};
        int dup = validator.findDuplicate(codes);
        log.info(() -> "Duplicated routing code: " + dup);
    }
}

