class RoutingCodeValidator {
    private static final Logger log = Logger.getLogger(RoutingCodeValidator.class.getName());

    // Floyd on index→value mapping. Read-only, O(n) time, O(1) space.
    int findDuplicate(int[] a) {
        int slow = a[0];          // phase 1: find a meeting point
        int fast = a[a[0]];
        while (slow != fast) {
            slow = a[slow];       // +1
            fast = a[a[fast]];    // +2
        }
        int finder = 0;           // phase 2: align from start
        while (finder != slow) {
            finder = a[finder];
            slow = a[slow];
        }
        int result = finder;
        log.warning(() -> "Duplicate detected: " + result);
        return result;            // cycle entry = duplicate value
    }
}

